25	constexpr const char* kVersionString = "envelopefile 0.1.0\n";
26	constexpr const char* kUsage =
27	    "Usage:\n"
28	    "  envelopefile --version\n"
29	    "  envelopefile keygen --output <path>\n"
30	    "  envelopefile encrypt --key <path> --input <path> --output <path>\n";
31	constexpr const char* kKeygenUsage =
