123	// Why a save attempt ended the way it did. kSaved is the only success; every
124	// other status is reported to the user with an explanatory message.
125	enum class KeySaveStatus {
126	    kSaved,          // all key bytes written, fsynced, and closed; mode 0600
127	    kNotCreated,     // open() produced no file, so nothing had to be cleaned
128	    kCleanedUp,      // this run created the file, failed, and removed it
129	    kCleanupFailed,  // this run created the file, failed, and removal failed
130	};
131	
132	// Complete outcome of one keygen save attempt: whether it succeeded, why it
133	// failed when it did, and whether the file this run created was cleaned up.
134	// The save logic itself writes nothing to stdout or stderr; the command line
135	// reports error, and additionally reports removalWarning only when cleanup
136	// failed, so a failed removal can never mask the original save failure and a
137	// caller can tell "removed" apart from "could not remove" instead of inferring
138	// deletion from failure alone. Neither string ever contains key material.
139	struct KeySaveResult {
140	    KeySaveStatus status = KeySaveStatus::kNotCreated;
141	    std::string error;           // why the save did not succeed; empty on success
142	    std::string removalWarning;  // populated only for kCleanupFailed
143	
144	    bool saved() const { return status == KeySaveStatus::kSaved; }
145	};
146	
147	// Owns the descriptor opened for the newly created key file for the duration
148	// of one save attempt and closes it exactly once. Closing is centralized here
149	// rather than spread across the failure branches: a branch only records its
150	// reason, and the descriptor is still released on every path out of scope.
151	class FdGuard {
152	public:
153	    FdGuard() = default;
154	    explicit FdGuard(int fd) : fd_(fd) {}
155	    ~FdGuard() { close(); }
156	
157	    FdGuard(const FdGuard&) = delete;
158	    FdGuard& operator=(const FdGuard&) = delete;
159	    FdGuard(FdGuard&&) = delete;
160	    FdGuard& operator=(FdGuard&&) = delete;
161	
162	    // Closes and disarms the guard, reporting close(2)'s status. Used after
163	    // fsync(), where a reported failure means durability could not be
164	    // confirmed and success must not be reported. Must be called while armed.
165	    int finish() {
166	        const int fd = fd_;
167	        fd_ = -1;
168	        return ::close(fd);
169	    }
170	
171	    // Best-effort close for failure paths: the save has already failed, and
172	    // close(2) releases the descriptor even when it reports an error, so the
173	    // result is intentionally discarded here. Idempotent via disarming.
174	    void close() {
175	        if (fd_ != -1) {
176	            const int fd = fd_;
177	            fd_ = -1;
178	            ::close(fd);
179	        }
180	    }
181	
182	private:
183	    int fd_ = -1;
184	};
