315	int runKeygen(int argc, char* argv[]) {
316	    std::string outputPath;
317	    bool haveOutput = false;
318	
319	    for (int i = 2; i < argc; ++i) {
320	        std::string_view arg(argv[i]);
321	        if (arg == "--output") {
322	            if (haveOutput) {
323	                std::cerr << "envelopefile: '--output' specified more than "
324	                             "once\n"
325	                          << kKeygenUsage;
326	                return 2;
327	            }
328	            if (i + 1 >= argc) {
329	                std::cerr << "envelopefile: option '--output' requires a "
330	                             "non-empty path\n"
331	                          << kKeygenUsage;
332	                return 2;
333	            }
334	            outputPath = argv[++i];
335	            if (outputPath.empty()) {
336	                std::cerr << "envelopefile: option '--output' requires a "
337	                             "non-empty path\n"
338	                          << kKeygenUsage;
339	                return 2;
340	            }
341	            haveOutput = true;
342	        } else {
343	            std::cerr << "envelopefile: unsupported argument: '" << arg
344	                      << "'\n"
345	                      << kKeygenUsage;
346	            return 2;
347	        }
348	    }
349	
350	    if (!haveOutput) {
351	        std::cerr << "envelopefile: missing required option '--output'\n"
352	                  << kKeygenUsage;
353	        return 2;
354	    }
355	
356	    SecureBuffer key(kKeyBytes);
357	    std::string error;
358	    if (!generateKey(key, error)) {
359	        std::cerr << "envelopefile: " << error << '\n';
360	        return 1;
361	    }
362	
363	    const KeySaveResult save = writeKeyFile(outputPath, key.data(), key.size());
364	    if (!save.saved()) {
365	        // The save logic reports outcomes as data; the command line owns all
366	        // user-facing messages. The original failure is always the primary
367	        // cause; a failed cleanup is reported only as an additional warning,
368	        // never as a replacement, so the exit code stays 1 and the user can
369	        // tell that an incomplete key file may remain.
370	        std::cerr << "envelopefile: " << save.error << '\n';
371	        if (save.status == KeySaveStatus::kCleanupFailed) {
372	            std::cerr << "envelopefile: warning: " << save.removalWarning
373	                      << '\n';
374	        }
375	        return 1;
376	    }
377	
378	    // key is wiped here by the SecureBuffer destructor; its contents never
379	    // reach stdout, stderr, or any log.
380	    std::cout << "envelopefile: 32-byte key generated and saved to '"
381	              << outputPath << "'\n";
382	    return 0;
383	}
