778	    // path itself, is rejected before it is touched.
779	    const EnvelopeSaveResult save = writeEnvelopeFile(outputPath, envelope);
780	    if (!save.saved()) {
781	        std::cerr << "envelopefile: " << save.error << '\n';
782	        if (save.status == KeySaveStatus::kCleanupFailed) {
783	            std::cerr << "envelopefile: warning: " << save.removalWarning
784	                      << '\n';
785	        }
786	        return 1;
787	    }
788	
789	    // The original input and key files are never opened for writing, so
790	    // their contents and permissions are unchanged. The key is wiped by the
791	    // SecureBuffer destructor as this scope exits.
792	    std::cout << "envelopefile: file encrypted and envelope saved to '"
793	              << outputPath << "'\n";
794	    return 0;
795	}
