#include <openssl/crypto.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#include <cerrno>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <fcntl.h>
#include <iostream>
#include <string>
#include <string_view>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <vector>

namespace {

constexpr std::size_t kKeyBytes = 32;
constexpr std::size_t kNonceBytes = 12;
constexpr std::size_t kTagBytes = 16;

constexpr const char* kVersionString = "envelopefile 0.1.0\n";
constexpr const char* kUsage =
    "Usage:\n"
    "  envelopefile --version\n"
    "  envelopefile keygen --output <path>\n"
    "  envelopefile encrypt --key <path> --input <path> --output <path>\n";
constexpr const char* kKeygenUsage =
    "Usage: envelopefile keygen --output <path>\n";
constexpr const char* kEncryptUsage =
    "Usage: envelopefile encrypt --key <path> --input <path> --output <path>\n";

// Binary envelope identification. The format is interpreted from these bytes,
// never from the file name/extension.
//
//   magic     "ENVFILE1"  7 bytes, fixed identification
//   version   uint8      1 byte,  format version (1)
//   algorithm uint8      1 byte,  algorithm identifier (1 = AES-256-GCM)
//   nonce     12 bytes            fresh per encryption
//   ciphertext N bytes            raw input bytes encrypted (may be empty)
//   tag       16 bytes            GCM authentication tag
//
// Everything from the first magic byte through the last ciphertext byte is
// the authenticated data, so the header used to interpret the envelope cannot
// be tampered with without detection. Multi-byte integer fields are single
// bytes here, so there is no endianness to decode.
constexpr unsigned char kEnvelopeMagic[7] = {
    'E', 'N', 'V', 'F', 'I', 'L', 'E'};
constexpr std::size_t kEnvelopeMagicBytes = 7;
constexpr std::size_t kHeaderBytes =
    kEnvelopeMagicBytes + 1 + 1 + kNonceBytes;  // 21 bytes
constexpr unsigned char kEnvelopeVersion = 1;
constexpr unsigned char kAlgAes256Gcm = 1;

// Owns raw key material and wipes it with OPENSSL_cleanse on every exit path.
class SecureBuffer {
public:
    SecureBuffer() = default;
    explicit SecureBuffer(std::size_t size) : size_(size) {
        data_ = new unsigned char[size_];
    }
    ~SecureBuffer() { wipe(); }

    SecureBuffer(const SecureBuffer&) = delete;
    SecureBuffer& operator=(const SecureBuffer&) = delete;
    SecureBuffer(SecureBuffer&& other) noexcept
        : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr;
        other.size_ = 0;
    }
    SecureBuffer& operator=(SecureBuffer&&) = delete;

    unsigned char* data() { return data_; }
    std::size_t size() const { return size_; }

    void wipe() {
        if (data_ != nullptr) {
            OPENSSL_cleanse(data_, size_);
            delete[] data_;
            data_ = nullptr;
            size_ = 0;
        }
    }

private:
    unsigned char* data_ = nullptr;
    std::size_t size_ = 0;
};

std::string opensslErrorString() {
    unsigned long code = ERR_peek_last_error();
    if (code == 0) {
        return {};
    }
    char buffer[256];
    ERR_error_string_n(code, buffer, sizeof(buffer));
    return buffer;
}

// Fills the buffer using OpenSSL's CSPRNG (backed by the operating system's
// secure random source). Never seeded from time, paths, or ordinary PRNGs.
bool generateKey(SecureBuffer& key, std::string& error) {
    if (RAND_bytes(key.data(), static_cast<int>(key.size())) != 1) {
        error = "secure random source failed";
        const std::string detail = opensslErrorString();
        if (!detail.empty()) {
            error += ": ";
            error += detail;
        }
        return false;
    }
    return true;
}

std::string errnoDescription(int errorNumber) {
    const char* description = std::strerror(errorNumber);
    return description != nullptr ? description : "unknown error";
}

// Why a save attempt ended the way it did. kSaved is the only success; every
// other status is reported to the user with an explanatory message.
enum class KeySaveStatus {
    kSaved,          // all key bytes written, fsynced, and closed; mode 0600
    kNotCreated,     // open() produced no file, so nothing had to be cleaned
    kCleanedUp,      // this run created the file, failed, and removed it
    kCleanupFailed,  // this run created the file, failed, and removal failed
};

// Complete outcome of one keygen save attempt: whether it succeeded, why it
// failed when it did, and whether the file this run created was cleaned up.
// The save logic itself writes nothing to stdout or stderr; the command line
// reports error, and additionally reports removalWarning only when cleanup
// failed, so a failed removal can never mask the original save failure and a
// caller can tell "removed" apart from "could not remove" instead of inferring
// deletion from failure alone. Neither string ever contains key material.
struct KeySaveResult {
    KeySaveStatus status = KeySaveStatus::kNotCreated;
    std::string error;           // why the save did not succeed; empty on success
    std::string removalWarning;  // populated only for kCleanupFailed

    bool saved() const { return status == KeySaveStatus::kSaved; }
};

// Owns the descriptor opened for the newly created key file for the duration
// of one save attempt and closes it exactly once. Closing is centralized here
// rather than spread across the failure branches: a branch only records its
// reason, and the descriptor is still released on every path out of scope.
class FdGuard {
public:
    FdGuard() = default;
    explicit FdGuard(int fd) : fd_(fd) {}
    ~FdGuard() { close(); }

    FdGuard(const FdGuard&) = delete;
    FdGuard& operator=(const FdGuard&) = delete;
    FdGuard(FdGuard&&) = delete;
    FdGuard& operator=(FdGuard&&) = delete;

    // Closes and disarms the guard, reporting close(2)'s status. Used after
    // fsync(), where a reported failure means durability could not be
    // confirmed and success must not be reported. Must be called while armed.
    int finish() {
        const int fd = fd_;
        fd_ = -1;
        return ::close(fd);
    }

    // Best-effort close for failure paths: the save has already failed, and
    // close(2) releases the descriptor even when it reports an error, so the
    // result is intentionally discarded here. Idempotent via disarming.
    void close() {
        if (fd_ != -1) {
            const int fd = fd_;
            fd_ = -1;
            ::close(fd);
        }
    }

private:
    int fd_ = -1;
};

// Forces the freshly created key file to exactly 0600: owner read/write, no
// execute bit, no group/other access. The mode given to open() is still
// reduced by the inherited process umask, which can strip owner read (umask
// 0400), owner write (umask 0200), or both (umask 0600); fchmod() is not
// affected by the umask. The result is verified with fstat() so a filesystem
// that silently keeps different permissions is treated as a failure instead
// of being reported as a success.
bool fixKeyFilePermissions(int fd, const std::string& path,
                           std::string& error) {
    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
        error = "cannot set key file permissions to 0600 on '" + path +
                "': " + errnoDescription(errno);
        return false;
    }
    struct stat info;
    if (::fstat(fd, &info) != 0) {
        error = "cannot verify key file permissions on '" + path +
                "': " + errnoDescription(errno);
        return false;
    }
    if ((info.st_mode & 0777) != (S_IRUSR | S_IWUSR)) {
        error = "cannot guarantee key file permissions 0600 on '" + path +
                "'";
        return false;
    }
    return true;
}

// Creates a brand new file containing exactly keySize raw bytes. Any existing
// path (file, directory, symlink including a dangling one) is rejected. The
// file is created with mode 0600 and its permissions are then forced to
// exactly 0600 (the creation mode alone is still subject to the umask) before
// any key byte is written; at no point is the file accessible to group or
// other users.
//
// The outcome is reported entirely through KeySaveResult: an open() failure
// creates nothing (kNotCreated); a failure after creation closes the
// descriptor via the FdGuard and removes this run's file, reporting either
// kCleanedUp or, if the removal itself failed, kCleanupFailed with the
// removal reason in removalWarning so the caller can warn that an incomplete
// key file may remain. This function never writes to stdout or stderr.
KeySaveResult writeKeyFile(const std::string& path,
                           const unsigned char* key,
                           std::size_t keySize) {
    KeySaveResult result;

    int fd = ::open(path.c_str(),
                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
                    S_IRUSR | S_IWUSR);
    if (fd == -1) {
        const int savedErrno = errno;
        // Pre-creation failure: nothing was created, so this must not enter
        // the "remove the new file" handling and an existing target's
        // content, permissions, and links are never touched.
        result.status = KeySaveStatus::kNotCreated;
        if (savedErrno == EEXIST || savedErrno == ELOOP) {
            result.error = "refusing to write, path already exists: " + path;
        } else {
            result.error = "cannot create key file '" + path + "': " +
                           errnoDescription(savedErrno);
        }
        return result;
    }

    FdGuard guard(fd);
    result.status = KeySaveStatus::kCleanedUp;  // assumed until the save completes
    std::string error;

    // If the permissions cannot be guaranteed, this run must not be reported
    // as a success even though the key was generated and the file was
    // created: skip the write and fall through to the cleanup below, before
    // any key byte reaches the file.
    if (fixKeyFilePermissions(fd, path, error)) {
        std::size_t totalWritten = 0;
        while (totalWritten < keySize) {
            ssize_t written =
                ::write(fd, key + totalWritten, keySize - totalWritten);
            if (written < 0) {
                if (errno == EINTR) {
                    continue;
                }
                error = "failed writing key file '" + path + "': " +
                        errnoDescription(errno);
                break;
            }
            if (written == 0) {
                error = "failed writing key file '" + path + "': short write";
                break;
            }
            totalWritten += static_cast<std::size_t>(written);
        }

        if (totalWritten == keySize) {
            if (::fsync(fd) != 0) {
                error = "failed syncing key file '" + path + "': " +
                        errnoDescription(errno);
            } else if (guard.finish() != 0) {
                // The descriptor is closed by the kernel even when close
                // fails, but durability could not be confirmed: do not
                // report success.
                error = "failed closing key file '" + path + "': " +
                        errnoDescription(errno);
            } else {
                // The complete original key is written, synced, and closed;
                // 0600 was verified before the first byte.
                result.status = KeySaveStatus::kSaved;
                result.error.clear();
                return result;
            }
        }
    }

    // Failure after creation. The descriptor opened by this run is closed
    // exactly once (guard.finish() above already disarmed it on the
    // close-failure path); removing the path cannot touch prior content
    // because O_EXCL guaranteed the file did not exist before open().
    guard.close();
    if (::unlink(path.c_str()) != 0 && errno != ENOENT) {
        // The original save failure remains the reported cause; this only
        // adds that the incomplete file could not be removed.
        result.status = KeySaveStatus::kCleanupFailed;
        result.removalWarning =
            "could not remove partial key file '" + path + "': " +
            errnoDescription(errno);
    }
    result.error = std::move(error);
    return result;
}

int runKeygen(int argc, char* argv[]) {
    std::string outputPath;
    bool haveOutput = false;

    for (int i = 2; i < argc; ++i) {
        std::string_view arg(argv[i]);
        if (arg == "--output") {
            if (haveOutput) {
                std::cerr << "envelopefile: '--output' specified more than "
                             "once\n"
                          << kKeygenUsage;
                return 2;
            }
            if (i + 1 >= argc) {
                std::cerr << "envelopefile: option '--output' requires a "
                             "non-empty path\n"
                          << kKeygenUsage;
                return 2;
            }
            outputPath = argv[++i];
            if (outputPath.empty()) {
                std::cerr << "envelopefile: option '--output' requires a "
                             "non-empty path\n"
                          << kKeygenUsage;
                return 2;
            }
            haveOutput = true;
        } else {
            std::cerr << "envelopefile: unsupported argument: '" << arg
                      << "'\n"
                      << kKeygenUsage;
            return 2;
        }
    }

    if (!haveOutput) {
        std::cerr << "envelopefile: missing required option '--output'\n"
                  << kKeygenUsage;
        return 2;
    }

    SecureBuffer key(kKeyBytes);
    std::string error;
    if (!generateKey(key, error)) {
        std::cerr << "envelopefile: " << error << '\n';
        return 1;
    }

    const KeySaveResult save = writeKeyFile(outputPath, key.data(), key.size());
    if (!save.saved()) {
        // The save logic reports outcomes as data; the command line owns all
        // user-facing messages. The original failure is always the primary
        // cause; a failed cleanup is reported only as an additional warning,
        // never as a replacement, so the exit code stays 1 and the user can
        // tell that an incomplete key file may remain.
        std::cerr << "envelopefile: " << save.error << '\n';
        if (save.status == KeySaveStatus::kCleanupFailed) {
            std::cerr << "envelopefile: warning: " << save.removalWarning
                      << '\n';
        }
        return 1;
    }

    // key is wiped here by the SecureBuffer destructor; its contents never
    // reach stdout, stderr, or any log.
    std::cout << "envelopefile: 32-byte key generated and saved to '"
              << outputPath << "'\n";
    return 0;
}

// ---------------------------------------------------------------------------
// encrypt
// ---------------------------------------------------------------------------

// Outcome of writing the already-sealed envelope bytes to a brand new file.
// Mirrors KeySaveResult: the sealing/encryption step is finished before this
// runs, so the only failures here concern creating and saving the output.
struct EnvelopeSaveResult {
    KeySaveStatus status = KeySaveStatus::kNotCreated;
    std::string error;
    std::string removalWarning;

    bool saved() const { return status == KeySaveStatus::kSaved; }
};

// Reads an entire file as raw bytes. The bytes are returned without any
// newline/NUL conversion; an empty file yields an empty vector. The path is
// never followed through a terminal symlink for the *output*, but key and
// input paths are opened normally (a symlink key/input is a legitimate file).
bool readAllBytes(const std::string& path, std::vector<unsigned char>& out,
                  std::string& error, const char* what) {
    int fd = ::open(path.c_str(), O_RDONLY);
    if (fd == -1) {
        error = std::string("cannot read ") + what + " '" + path + "': " +
                errnoDescription(errno);
        return false;
    }
    FdGuard guard(fd);

    out.clear();
    unsigned char chunk[4096];
    for (;;) {
        ssize_t got = ::read(fd, chunk, sizeof(chunk));
        if (got < 0) {
            if (errno == EINTR) {
                continue;
            }
            error = std::string("failed reading ") + what + " '" + path +
                    "': " + errnoDescription(errno);
            return false;
        }
        if (got == 0) {
            break;  // end of file
        }
        out.insert(out.end(), chunk, chunk + static_cast<std::size_t>(got));
    }
    return true;
}

// Reads exactly kKeyBytes (32) raw bytes from the key file: no trailing data,
// no text decoding, no substitute key. A short or long file is an error.
bool readKeyFile(const std::string& path, SecureBuffer& key,
                 std::string& error) {
    int fd = ::open(path.c_str(), O_RDONLY);
    if (fd == -1) {
        error = "cannot read key file '" + path + "': " +
                errnoDescription(errno);
        return false;
    }
    FdGuard guard(fd);

    std::size_t total = 0;
    while (total < kKeyBytes) {
        ssize_t got = ::read(fd, key.data() + total, kKeyBytes - total);
        if (got < 0) {
            if (errno == EINTR) {
                continue;
            }
            error = "failed reading key file '" + path + "': " +
                    errnoDescription(errno);
            return false;
        }
        if (got == 0) {
            error = "key file '" + path + "' is " +
                    std::to_string(total) + " bytes, expected exactly " +
                    std::to_string(kKeyBytes);
            return false;
        }
        total += static_cast<std::size_t>(got);
    }

    // The file must contain exactly the key, nothing after it.
    unsigned char extra;
    ssize_t got;
    do {
        got = ::read(fd, &extra, 1);
    } while (got < 0 && errno == EINTR);
    if (got < 0) {
        error = "failed reading key file '" + path + "': " +
                errnoDescription(errno);
        return false;
    }
    if (got > 0) {
        error = "key file '" + path + "' is longer than " +
                std::to_string(kKeyBytes) +
                " bytes; expected exactly 32 raw key bytes";
        return false;
    }
    return true;
}

// Seals plaintext with AES-256-GCM and builds the complete envelope. The
// header (magic/version/algorithm/nonce) is supplied as authenticated data so
// the bytes used to interpret the envelope are covered by the tag. On success
// envelope holds header || ciphertext || tag; on failure it returns false and
// sets error, without ever generating a substitute key.
bool sealEnvelope(const unsigned char* key,
                  const std::vector<unsigned char>& plaintext,
                  std::vector<unsigned char>& envelope,
                  std::string& error) {
    unsigned char nonce[kNonceBytes];
    if (RAND_bytes(nonce, static_cast<int>(kNonceBytes)) != 1) {
        error = "secure random source failed";
        const std::string detail = opensslErrorString();
        if (!detail.empty()) {
            error += ": ";
            error += detail;
        }
        OPENSSL_cleanse(nonce, sizeof(nonce));
        return false;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == nullptr) {
        error = "cannot initialize AES-256-GCM";
        OPENSSL_cleanse(nonce, sizeof(nonce));
        return false;
    }

    int outLen = 0;
    const std::size_t bodySize = plaintext.size();
    envelope.resize(kHeaderBytes + bodySize + kTagBytes);
    unsigned char* body = envelope.data() + kHeaderBytes;
    unsigned char* tag = body + bodySize;

    auto fail = [&](const std::string& message) {
        error = message;
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_cleanse(nonce, sizeof(nonce));
        // Do not leave partial ciphertext in the caller's buffer.
        if (!envelope.empty()) {
            OPENSSL_cleanse(envelope.data(), envelope.size());
        }
        envelope.clear();
    };

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr,
                           nullptr) != 1) {
        fail("AES-256-GCM initialization failed");
        return false;
    }
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN,
                            static_cast<int>(kNonceBytes), nullptr) != 1) {
        fail("cannot set GCM nonce length");
        return false;
    }
    if (EVP_EncryptInit_ex(ctx, nullptr, nullptr, key, nonce) != 1) {
        fail("cannot set GCM key and nonce");
        return false;
    }

    // Build the header first and authenticate it before any plaintext byte,
    // so magic/version/algorithm/nonce are all bound to the tag. A null output
    // marks these bytes as additional authenticated data; OpenSSL reports the
    // AAD length back, so use a dedicated counter for ciphertext below rather
    // than reusing this one (it would otherwise spoil the empty-input check).
    unsigned char* header = envelope.data();
    std::memcpy(header, kEnvelopeMagic, kEnvelopeMagicBytes);
    header[kEnvelopeMagicBytes] = kEnvelopeVersion;
    header[kEnvelopeMagicBytes + 1] = kAlgAes256Gcm;
    std::memcpy(header + kEnvelopeMagicBytes + 2, nonce, kNonceBytes);

    if (EVP_EncryptUpdate(ctx, nullptr, &outLen, header,
                          static_cast<int>(kHeaderBytes)) != 1) {
        fail("cannot authenticate envelope header");
        return false;
    }

    int ciphertextLen = 0;
    if (!plaintext.empty()) {
        if (EVP_EncryptUpdate(ctx, body, &ciphertextLen, plaintext.data(),
                              static_cast<int>(plaintext.size())) != 1) {
            fail("encryption failed");
            return false;
        }
    }
    int finalLen = 0;
    if (EVP_EncryptFinal_ex(ctx, body + ciphertextLen, &finalLen) != 1) {
        fail("encryption finalization failed");
        return false;
    }
    if (static_cast<std::size_t>(ciphertextLen) +
            static_cast<std::size_t>(finalLen) !=
        bodySize) {
        fail("ciphertext length mismatch");
        return false;
    }
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG,
                            static_cast<int>(kTagBytes), tag) != 1) {
        fail("cannot obtain authentication tag");
        return false;
    }

    EVP_CIPHER_CTX_free(ctx);
    OPENSSL_cleanse(nonce, sizeof(nonce));
    return true;
}

// Writes the sealed envelope to a brand new file, rejecting every kind of
// existing path (regular file, empty file, directory, symlink including a
// dangling one) via O_CREAT|O_EXCL|O_NOFOLLOW. The envelope file is created
// readable by the owner (0600) because it is encrypted output; unlike keygen
// the 0600 mode is not force-verified here, but group/other never gain access
// at creation. A failure after creation closes and removes this run's file,
// reporting kCleanupFailed (with a warning) only if that removal fails.
EnvelopeSaveResult writeEnvelopeFile(const std::string& path,
                                     const std::vector<unsigned char>& bytes) {
    EnvelopeSaveResult result;

    int fd = ::open(path.c_str(),
                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
                    S_IRUSR | S_IWUSR);
    if (fd == -1) {
        const int savedErrno = errno;
        result.status = KeySaveStatus::kNotCreated;
        if (savedErrno == EEXIST || savedErrno == ELOOP) {
            result.error = "refusing to write, path already exists: " + path;
        } else {
            result.error = "cannot create envelope file '" + path + "': " +
                           errnoDescription(savedErrno);
        }
        return result;
    }

    FdGuard guard(fd);
    result.status = KeySaveStatus::kCleanedUp;
    std::string error;

    // Envelope output is ciphertext plus a tag; restrict it to owner access.
    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
        error = "cannot set envelope file permissions to 0600 on '" + path +
                "': " + errnoDescription(errno);
    } else {
        std::size_t total = 0;
        while (total < bytes.size()) {
            ssize_t written =
                ::write(fd, bytes.data() + total, bytes.size() - total);
            if (written < 0) {
                if (errno == EINTR) {
                    continue;
                }
                error = "failed writing envelope file '" + path + "': " +
                        errnoDescription(errno);
                break;
            }
            if (written == 0) {
                error = "failed writing envelope file '" + path +
                        "': short write";
                break;
            }
            total += static_cast<std::size_t>(written);
        }

        if (total == bytes.size()) {
            if (::fsync(fd) != 0) {
                error = "failed syncing envelope file '" + path + "': " +
                        errnoDescription(errno);
            } else if (guard.finish() != 0) {
                error = "failed closing envelope file '" + path + "': " +
                        errnoDescription(errno);
            } else {
                result.status = KeySaveStatus::kSaved;
                result.error.clear();
                return result;
            }
        }
    }

    guard.close();
    if (::unlink(path.c_str()) != 0 && errno != ENOENT) {
        result.status = KeySaveStatus::kCleanupFailed;
        result.removalWarning =
            "could not remove partial envelope file '" + path + "': " +
            errnoDescription(errno);
    }
    result.error = std::move(error);
    return result;
}

int runEncrypt(int argc, char* argv[]) {
    std::string keyPath;
    std::string inputPath;
    std::string outputPath;
    bool haveKey = false;
    bool haveInput = false;
    bool haveOutput = false;

    // All-or-nothing parse: validate the whole argument list and reject the
    // entire operation (exit 2) before any file is read or created.
    for (int i = 2; i < argc; ++i) {
        std::string_view arg(argv[i]);
        std::string_view option;
        std::string* target = nullptr;
        bool* seen = nullptr;

        if (arg == "--key") {
            option = "--key";
            target = &keyPath;
            seen = &haveKey;
        } else if (arg == "--input") {
            option = "--input";
            target = &inputPath;
            seen = &haveInput;
        } else if (arg == "--output") {
            option = "--output";
            target = &outputPath;
            seen = &haveOutput;
        } else {
            std::cerr << "envelopefile: unsupported argument: '" << arg
                      << "'\n"
                      << kEncryptUsage;
            return 2;
        }

        if (*seen) {
            std::cerr << "envelopefile: '" << option
                      << "' specified more than once\n"
                      << kEncryptUsage;
            return 2;
        }
        if (i + 1 >= argc) {
            std::cerr << "envelopefile: option '" << option
                      << "' requires a non-empty path\n"
                      << kEncryptUsage;
            return 2;
        }
        *target = argv[++i];
        if (target->empty()) {
            std::cerr << "envelopefile: option '" << option
                      << "' requires a non-empty path\n"
                      << kEncryptUsage;
            return 2;
        }
        *seen = true;
    }

    if (!haveKey || !haveInput || !haveOutput) {
        if (!haveKey) {
            std::cerr << "envelopefile: missing required option '--key'\n"
                      << kEncryptUsage;
        } else if (!haveInput) {
            std::cerr << "envelopefile: missing required option '--input'\n"
                      << kEncryptUsage;
        } else {
            std::cerr << "envelopefile: missing required option '--output'\n"
                      << kEncryptUsage;
        }
        return 2;
    }

    // Read the exact 32-byte raw key. This buffer is wiped on every exit
    // path (success or failure), so the key never survives the operation in
    // memory and never reaches stdout/stderr.
    SecureBuffer key(kKeyBytes);
    {
        std::string error;
        if (!readKeyFile(keyPath, key, error)) {
            std::cerr << "envelopefile: " << error << '\n';
            return 1;
        }
    }

    // Read the input as raw bytes (no conversion; empty input is allowed).
    std::vector<unsigned char> plaintext;
    {
        std::string error;
        if (!readAllBytes(inputPath, plaintext, error, "input file")) {
            std::cerr << "envelopefile: " << error << '\n';
            return 1;
        }
    }

    // Seal with a fresh random nonce and an authenticated header.
    std::vector<unsigned char> envelope;
    {
        std::string error;
        if (!sealEnvelope(key.data(), plaintext, envelope, error)) {
            std::cerr << "envelopefile: " << error << '\n';
            return 1;
        }
    }

    // Save to a brand new path; any existing path, including the input or key
    // path itself, is rejected before it is touched.
    const EnvelopeSaveResult save = writeEnvelopeFile(outputPath, envelope);
    if (!save.saved()) {
        std::cerr << "envelopefile: " << save.error << '\n';
        if (save.status == KeySaveStatus::kCleanupFailed) {
            std::cerr << "envelopefile: warning: " << save.removalWarning
                      << '\n';
        }
        return 1;
    }

    // The original input and key files are never opened for writing, so
    // their contents and permissions are unchanged. The key is wiped by the
    // SecureBuffer destructor as this scope exits.
    std::cout << "envelopefile: file encrypted and envelope saved to '"
              << outputPath << "'\n";
    return 0;
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc == 2 && std::string_view(argv[1]) == "--version") {
        std::cout << kVersionString;
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "keygen") {
        return runKeygen(argc, argv);
    }

    if (argc >= 2 && std::string_view(argv[1]) == "encrypt") {
        return runEncrypt(argc, argv);
    }

    std::cerr << kUsage;
    return 2;
}

// Fault-injection shims for the regression-test build of envelopefile.
//
// This file is linked together with src/main.cpp into the separate
// `envelopefile_testable` binary using the linker's --wrap option, so every
// open/write/fsync/close/unlink call made by the product code is routed
// through the __wrap_* functions below. The production binary is completely
// unaffected.
//
// Injection is controlled entirely through environment variables so the test
// driver can select a scenario per process run:
//
//   EF_TEST_TARGET          Only inject faults for this exact path. When
//                           unset, any file created with O_CREAT|O_EXCL is
//                           considered the key file under test.
//   EF_TEST_FAIL_WRITE=1    write() on the key file fails with EIO.
//   EF_TEST_PARTIAL_WRITE=N write() on the key file returns at most N bytes
//                           per call (the caller must loop to complete).
//   EF_TEST_FAIL_FSYNC=1    fsync() on the key file fails with EIO.
//   EF_TEST_FAIL_CLOSE=1    close() on the key file reports EIO (the
//                           descriptor is still really closed, matching the
//                           POSIX guarantee that close() releases the fd).
//   EF_TEST_FAIL_UNLINK=1   unlink() of the key file fails with EIO after a
//                           save failure, simulating cleanup that cannot
//                           remove the incomplete file the run just created.
//                           The key file is really left on disk. Only the
//                           path created by this run is affected: unlinks of
//                           any other path pass through untouched.
//   EF_TEST_FAIL_OPEN=1     the key file's open(O_CREAT|O_EXCL) fails BEFORE
//                           any file is created — the real syscall is never
//                           reached — simulating a save location that refuses
//                           to accept the new file at creation time. The errno
//                           defaults to EACCES (a parent directory that denies
//                           creation) and can be overridden with the decimal
//                           value in EF_TEST_OPEN_ERRNO. Because the refusal
//                           is injected, the scenario is real even when the
//                           test process runs with effective permission in the
//                           directory (e.g. as root), and nothing is left on
//                           disk, so the product's pre-creation ("not created")
//                           path is exercised rather than its post-creation
//                           cleanup. Only the O_CREAT|O_EXCL key-file open is
//                           matched, so log files and every other open pass
//                           through untouched.
//   EF_TEST_FAIL_FCHMOD=1   fchmod() on the key file fails with EPERM, so the
//                           0600 permission guarantee cannot be established.
//   EF_TEST_FAIL_FSTAT=1    fstat() on the key file fails with EIO even though
//                           fchmod() reported success: the post-set permission
//                           verification cannot read the file's metadata.
//   EF_TEST_FSTAT_MODE=mmm  fstat() succeeds but the permission bits reported
//                           back are replaced with the octal mode mmm (only the
//                           low 12 bits are taken; file type bits are kept),
//                           simulating a filesystem where fchmod() reports
//                           success but the effective mode differs, e.g. 0644
//                           (group/other can still read) or 0400 (owner write
//                           was stripped).
//
// For deterministic coverage of the write loop itself, a per-call script can
// be supplied:
//
//   EF_TEST_WRITE_SCRIPT=t1,t2,...
//                           Each token describes the outcome of one write()
//                           call on the key file, consumed in order; once the
//                           list is exhausted every further call succeeds
//                           normally. Tokens:
//                             ok    - write the whole requested buffer
//                             N     - short write: at most N (decimal) bytes
//                             intr  - fail with EINTR, no bytes written
//                             eio   - fail irrecoverably with EIO
//                             zero  - return 0 with bytes still pending
//
//   EF_TEST_WRITE_LOG=path  Record what the write loop actually did, so the
//                           test driver can prove byte continuity across
//                           retries. On the first key-file write the original
//                           32-byte key is snapshotted; every subsequent call
//                           is checked to advance from the current offset with
//                           a buffer that is a slice of that same snapshot
//                           (i.e. the key is neither regenerated, duplicated,
//                           nor dropped). Every call is also checked to pass a
//                           pointer INTO the exact buffer RAND_bytes filled
//                           (at the current offset), so the bytes that reach
//                           the file are provably the ones the later
